{
  "vision": "Enable international expansion by migrating customer profiles from PostgreSQL to MongoDB, supporting flexible country-specific data and zero downtime. This will reduce schema management overhead and ensure full backward compatibility for existing APIs.",
  "scope": "Migrate ~2 million customer records (~150GB) from PostgreSQL to MongoDB. Implement dual-write and CDC for seamless data synchronization, maintain API stability, and ensure performance parity. Configure MongoDB indexes and validation checks for exact data parity. Out of scope: non-customer-related tables, UI changes, or external APIs.",
  "success_criteria": [
    "100% parity between PostgreSQL and MongoDB before cutover",
    "Zero data loss and <50ms (p95) read latency after migration",
    "Dual-write and rollback mechanisms validated within 2 weeks",
    "Successful feature-flag-based rollout with backward-compatible API"
  ],
  "user_stories": [
    {
      "id": "US-001",
      "title": "Design MongoDB schema for flexible country-specific customer data",
      "as_a": "data architect",
      "i_want": "to define a MongoDB schema that supports variable country-specific fields",
      "so_that": "we can store regulatory data without future schema migrations",
      "acceptance_criteria": [
        {"given": "a set of international customer requirements", "when": "the schema is designed", "then": "it supports fields like My Number or VAT ID per country without altering other documents"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["schema", "mongodb", "architecture"]
    },
    {
      "id": "US-002",
      "title": "Implement CDC pipeline for backfill from PostgreSQL to MongoDB",
      "as_a": "data engineer",
      "i_want": "to configure and monitor CDC for incremental data migration",
      "so_that": "customer data stays synchronized during dual-write period",
      "acceptance_criteria": [
        {"given": "existing PostgreSQL tables", "when": "CDC is activated", "then": "changes are captured and mirrored into MongoDB with zero data loss"}
      ],
      "priority": "High",
      "story_points": 8,
      "labels": ["cdc", "migration", "data-synchronization"]
    },
    {
      "id": "US-003",
      "title": "Implement dual-write mechanism to both PostgreSQL and MongoDB during transition",
      "as_a": "backend engineer",
      "i_want": "writes to be persisted in both databases during migration",
      "so_that": "we can ensure data consistency while validating MongoDB performance",
      "acceptance_criteria": [
        {"given": "a write request to the customer profile API", "when": "dual-write mode is active", "then": "data is saved successfully to both PostgreSQL and MongoDB"}
      ],
      "priority": "High",
      "story_points": 8,
      "labels": ["dual-write", "api", "migration"]
    },
    {
      "id": "US-004",
      "title": "Add feature flag to enable gradual rollout of MongoDB-backed customer data",
      "as_a": "release manager",
      "i_want": "to control the rollout of MongoDB reads and writes through feature flags",
      "so_that": "migration can occur without downtime or customer impact",
      "acceptance_criteria": [
        {"given": "the application configuration", "when": "feature flag is toggled on", "then": "requests start reading from MongoDB instead of PostgreSQL"}
      ],
      "priority": "Medium",
      "story_points": 5,
      "labels": ["feature-flag", "rollout", "zero-downtime"]
    },
    {
      "id": "US-005",
      "title": "Perform data validation and parity check between PostgreSQL and MongoDB",
      "as_a": "QA engineer",
      "i_want": "to ensure all customer records match between both databases before cutover",
      "so_that": "we guarantee zero data loss and maintain data integrity",
      "acceptance_criteria": [
        {"given": "complete data in both databases", "when": "validation script runs", "then": "it reports 100% parity or highlights discrepancies for review"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["validation", "data-integrity", "migration-check"]
    },
    {
      "id": "US-006",
      "title": "Create rollback procedure to revert API reads/writes to PostgreSQL within 1 hour",
      "as_a": "release engineer",
      "i_want": "a tested rollback plan for database migration",
      "so_that": "we can quickly restore service in case of MongoDB issues",
      "acceptance_criteria": [
        {"given": "MongoDB deployment is live", "when": "rollback is initiated", "then": "API is reverted fully to PostgreSQL operations within 60 minutes"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["rollback", "disaster-recovery", "api-stability"]
    },
    {
      "id": "US-007",
      "title": "Optimize MongoDB indexes for read/write performance",
      "as_a": "database administrator",
      "i_want": "to define and create indexes that meet <50ms read latency targets",
      "so_that": "customer data queries perform as efficiently as PostgreSQL",
      "acceptance_criteria": [
        {"given": "a set of customer query patterns", "when": "indexes are created", "then": "read latency meets <50ms p95 performance under expected traffic"}
      ],
      "priority": "Medium",
      "story_points": 3,
      "labels": ["performance", "indexing", "mongodb"]
    }
  ]
}

{
  "architecture_overview": "The migration architecture employs a zero-downtime dual-write strategy with real-time CDC synchronization between the existing PostgreSQL relational database and a new MongoDB document store. The customer service API layer is updated to abstract database operations behind a data access layer, allowing feature flag-driven reads and writes to either or both stores. The MongoDB cluster is deployed as a 3-node replica set in AWS us-east-1 to ensure high availability and performance. CDC is implemented using AWS DMS (or Debezium) to stream updates from PostgreSQL to MongoDB, ensuring continuous synchronization during the dual-write period. Validation scripts will perform full parity checks between both data stores before cutover, and rollback mechanisms are provided to revert to PostgreSQL if necessary.",
  "technology_stack": ["Node.js", "Express.js", "PostgreSQL", "MongoDB Atlas", "AWS DMS", "Debezium", "Feature Flags (LaunchDarkly)", "Jest for testing", "AWS CloudWatch"],
  "api_endpoints": [
    {
      "method": "GET",
      "path": "/api/customers/:id",
      "description": "Retrieve a customer profile. Reads from PostgreSQL or MongoDB based on feature flag configuration.",
      "request_body": "None",
      "response": "{ 'id': string, 'name': string, 'country': string, 'countrySpecificFields': object }"
    },
    {
      "method": "POST",
      "path": "/api/customers",
      "description": "Create or update a customer record during dual-write period. Writes to both PostgreSQL and MongoDB with transactional guarantees.",
      "request_body": "{ 'name': string, 'country': string, 'countrySpecificFields': object }",
      "response": "{ 'status': 'success', 'id': string }"
    },
    {
      "method": "GET",
      "path": "/api/migration/validation/status",
      "description": "Return progress and statistics of data parity validation between PostgreSQL and MongoDB.",
      "request_body": "None",
      "response": "{ 'completed': boolean, 'recordsValidated': number, 'discrepancies': number }"
    },
    {
      "method": "POST",
      "path": "/api/admin/rollback",
      "description": "Trigger rollback of API reads/writes to PostgreSQL within one hour window.",
      "request_body": "{ 'confirmRollback': boolean }",
      "response": "{ 'status': 'initiated', 'remainingSteps': [string] }"
    }
  ],
  "database_schema": "MongoDB Document Model: {\n  _id: ObjectId,\n  customerId: String,\n  name: String,\n  email: String,\n  country: String,\n  countrySpecificFields: {\n    jp_myNumber: String?,\n    eu_vatId: String?,\n    us_ssn: String?,\n    otherFields: Map<String, Any>\n  },\n  createdAt: Date,\n  updatedAt: Date\n}\nIndexes:\n  1. { customerId: 1 }\n  2. { email: 1 }\n  3. { country: 1 }\n  4. { countrySpecificFields.eu_vatId: 1 }\nPostgreSQL schema remains unchanged; read/write operations occur via existing ORM models during dual-write.",
  "security_considerations": [
    "Encrypt sensitive regulatory fields (My Number, VAT ID) at rest using MongoDB's client-side field-level encryption.",
    "Ensure secure TLS connections for all database traffic (PostgreSQL and MongoDB).",
    "Implement IAM-based access control on AWS for CDC connectors.",
    "Use API-level authentication and authorization via JWT or OAuth.",
    "Validate rollback and CDC scripts for idempotency and restricted operational access.",
    "Rotate all database credentials post-cutover as part of security hardening."
  ],
  "code_structure": {
    "root": "customer-service/",
    "folders": {
      "src/": {
        "api/": "Express API route definitions (customers, migration, admin).",
        "controllers/": "Controller logic for read/write and migration ops.",
        "services/": {
          "postgresService.js": "Handles reads/writes to PostgreSQL.",
          "mongoService.js": "Handles reads/writes to MongoDB.",
          "dualWriteService.js": "Coordinates parallel writes and rollback triggers.",
          "cdcService.js": "Interfaces with AWS DMS or Debezium connector."
        },
        "utils/": "Feature flag utilities, validation scripts, logging wrappers.",
        "config/": "Database connection configurations, environment setup.",
        "tests/": "Unit and integration test definitions using Jest."
      },
      "scripts/": "CDC validation scripts and parity checks.",
      "docs/": "Rollback procedures, migration instructions."
    }
  },
  "implementation_notes": "1. Dual-write implementation should batch writes and perform acknowledgements only after both databases confirm success.\n2. CDC connector configuration uses PostgreSQL WAL for incremental updates and applies changes via DMS or Debezium stream to MongoDB.\n3. Feature flags control read source selection dynamically, enabling progressive rollout without downtime.\n4. Parity validator runs as a background job comparing hashes of records between both databases to ensure full data integrity before cutover.\n5. MongoDB indexes are pre-created for high-frequency queries to maintain <50ms p95 read latency under 5,000 reads/sec.\n6. The rollback plan involves toggling the feature flag back to PostgreSQL-only mode and disabling CDC writes, ensuring return to stable state within one hour.\n7. Ensure monitoring dashboards (CloudWatch) track CDC lag, MongoDB replication status, and dual-write errors with automated alerts."
}

{
  "summary": "Implementation of migration architecture from PostgreSQL to MongoDB with dual-write and CDC synchronization. Includes API layer updates for feature flag-based read/write routing, MongoDB schema design, validation parity utilities, and rollback endpoint for zero-downtime migration.",
  "code_files": [
    {
      "filename": "src/controllers/customerController.js",
      "language": "javascript",
      "description": "Controller implementing customer read/write logic with feature flag-controlled source selection and dual-write capability.",
      "code": "const featureFlag = require('../utils/featureFlag');
const postgresService = require('../services/postgresService');
const mongoService = require('../services/mongoService');
const dualWriteService = require('../services/dualWriteService');

// GET /api/customers/:id
exports.getCustomerById = async (req, res) => {
  try {
    const { id } = req.params;
    const useMongo = await featureFlag.isEnabled('useMongoReads');
    let customer;

    if (useMongo) {
      customer = await mongoService.findById(id);
    } else {
      customer = await postgresService.findById(id);
    }

    if (!customer) {
      return res.status(404).json({ error: 'Customer not found' });
    }

    res.json(customer);
  } catch (error) {
    console.error('Error retrieving customer:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

// POST /api/customers
exports.createOrUpdateCustomer = async (req, res) => {
  try {
    const data = req.body;
    const dualWriteEnabled = await featureFlag.isEnabled('dualWriteMode');

    let response;

    if (dualWriteEnabled) {
      response = await dualWriteService.save(data);
    } else {
      response = await postgresService.save(data);
    }

    res.json({ status: 'success', id: response.id });
  } catch (error) {
    console.error('Error saving customer:', error);
    res.status(500).json({ error: 'Save Failed' });
  }
};"
    },
    {
      "filename": "src/services/dualWriteService.js",
      "language": "javascript",
      "description": "Service to handle transactional dual writes to PostgreSQL and MongoDB ensuring data consistency.",
      "code": "const postgresService = require('./postgresService');
const mongoService = require('./mongoService');

exports.save = async (data) => {
  try {
    const pgResult = await postgresService.save(data);
    const mongoResult = await mongoService.save(data);

    if (!pgResult || !mongoResult) {
      throw new Error('Dual-write failure');
    }

    return { id: pgResult.id };
  } catch (error) {
    console.error('Dual-write error:', error);
    throw error;
  }
};"
    },
    {
      "filename": "src/services/postgresService.js",
      "language": "javascript",
      "description": "Handles PostgreSQL read/write operations using pg client.",
      "code": "const { Pool } = require('pg');
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

exports.findById = async (id) => {
  const result = await pool.query('SELECT * FROM customers WHERE id = $1', [id]);
  return result.rows[0];
};

exports.save = async (data) => {
  const result = await pool.query('INSERT INTO customers (name, country, email) VALUES ($1, $2, $3) RETURNING id', [data.name, data.country, data.email]);
  return result.rows[0];
};"
    },
    {
      "filename": "src/services/mongoService.js",
      "language": "javascript",
      "description": "Handles MongoDB read/write operations for flexible country-specific schema.",
      "code": "const { MongoClient } = require('mongodb');
const client = new MongoClient(process.env.MONGO_URI);
let collection;

(async () => {
  await client.connect();
  collection = client.db('customerdb').collection('customers');
})();

exports.findById = async (id) => {
  return await collection.findOne({ customerId: id });
};

exports.save = async (data) => {
  const doc = {
    customerId: data.id || new Date().getTime().toString(),
    name: data.name,
    email: data.email,
    country: data.country,
    countrySpecificFields: data.countrySpecificFields || {},
    createdAt: new Date(),
    updatedAt: new Date()
  };
  await collection.updateOne({ customerId: doc.customerId }, { $set: doc }, { upsert: true });
  return { id: doc.customerId };
};"
    },
    {
      "filename": "src/utils/featureFlag.js",
      "language": "javascript",
      "description": "Feature flag utility integrating with LaunchDarkly for zero-downtime rollout control.",
      "code": "const LaunchDarkly = require('launchdarkly-node-server-sdk');
const ldClient = LaunchDarkly.init(process.env.LAUNCHDARKLY_SDK_KEY);

exports.isEnabled = async (flagKey) => {
  await ldClient.waitForInitialization();
  const result = await ldClient.variation(flagKey, { key: 'system-user' }, false);
  return result;
};"
    },
    {
      "filename": "src/controllers/migrationController.js",
      "language": "javascript",
      "description": "Controller for migration validation progress and rollback triggers.",
      "code": "const validationService = require('../services/validationService');
const rollbackService = require('../services/rollbackService');

exports.getValidationStatus = async (req, res) => {
  try {
    const status = await validationService.getStatus();
    res.json(status);
  } catch (error) {
    console.error('Validation status error:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

exports.initiateRollback = async (req, res) => {
  try {
    const { confirmRollback } = req.body;
    if (!confirmRollback) {
      return res.status(400).json({ error: 'Confirmation required' });
    }
    const result = await rollbackService.triggerRollback();
    res.json(result);
  } catch (error) {
    console.error('Rollback error:', error);
    res.status(500).json({ error: 'Rollback Failed' });
  }
};"
    },
    {
      "filename": "src/services/validationService.js",
      "language": "javascript",
      "description": "Validation service for data parity check between PostgreSQL and MongoDB.",
      "code": "const postgresService = require('./postgresService');
const mongoService = require('./mongoService');

let status = { completed: false, recordsValidated: 0, discrepancies: 0 };

exports.getStatus = async () => status;

exports.validateParity = async () => {
  const pgCustomers = await postgresService.getAll();
  let validated = 0;
  let discrepancies = 0;

  for (const cust of pgCustomers) {
    const mongoCust = await mongoService.findById(cust.id);
    if (JSON.stringify(cust) !== JSON.stringify(mongoCust)) discrepancies++;
    validated++;
  }

  status = { completed: true, recordsValidated: validated, discrepancies };
  return status;
};"
    }
  ],
  "setup_instructions": ["npm install", "npm run dev", "Configure LaunchDarkly SDK Key and database URIs in .env", "Ensure AWS DMS CDC connector is active before dual-write"],
  "environment_variables": [
    {
      "name": "DATABASE_URL",
      "description": "PostgreSQL connection string",
      "example": "postgresql://user:pass@localhost:5432/customers"
    },
    {
      "name": "MONGO_URI",
      "description": "MongoDB Atlas connection URI",
      "example": "mongodb+srv://user:pass@cluster0.mongodb.net/customerdb"
    },
    {
      "name": "LAUNCHDARKLY_SDK_KEY",
      "description": "LaunchDarkly SDK key for feature flag control",
      "example": "your-launchdarkly-sdk-key"
    }
  ],
  "dependencies": [
    {
      "name": "express",
      "version": "^4.18.0",
      "purpose": "Web framework for API routing"
    },
    {
      "name": "pg",
      "version": "^8.10.0",
      "purpose": "PostgreSQL client for Node.js connections"
    },
    {
      "name": "mongodb",
      "version": "^6.0.0",
      "purpose": "MongoDB client library for database operations"
    },
    {
      "name": "launchdarkly-node-server-sdk",
      "version": "^7.0.0",
      "purpose": "Feature flag integration for phased rollout"
    },
    {
      "name": "dotenv",
      "version": "^16.0.0",
      "purpose": "Environment variable management"
    }
  ]
}
